const body = $('Webhook - 本地 Agent 创建 Linear Issue').first().json.body || {};

// 支持两种入参：
// 1) issue 字段内放 Linear Issue 参数：{ issue: { title, description, ... }, feishu: {...} }
// 2) 所有字段直接平铺在 body 顶层。
// 注意：当前 n8n 环境不允许访问环境变量，因此不要读取 $env。
// 字段映射属于 workflow 内部实现细节，不要求本地 Agent 传 field_names。
const issue = body.issue && typeof body.issue === 'object' ? body.issue : body;
const feishuInput = body.feishu && typeof body.feishu === 'object' ? body.feishu : {};

// 如果不想让本地 Agent 每次传 app_token/table_id，可以把固定值写在这里。
const DEFAULT_FEISHU_CONFIG = {
  app_token: '',
  table_id: ''
};

// 你的飞书原表字段名固定写在 workflow 内部。
// 后续表结构变化，只改这里，不让本地 Agent 每次传字段映射。
const FIELD_NAMES = {
  parent_link: '父记录',
  title: '任务标题',
  description: '需求描述',
  linear_issue_id: 'Linear Issue ID',
  linear_url: 'Linear URL',
  agent_status: 'Agent 状态',
  task_type: '任务类型',
  priority: '优先级',
  repository: '目标仓库',
  base_branch: 'Base Branch'
};

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
}

function extractRecordIdFromUrl(url) {
  if (!url) return '';
  const text = String(url);
  const pathMatch = text.match(/\/record\/([A-Za-z0-9]+)/);
  if (pathMatch) return pathMatch[1];
  const queryMatch = text.match(/[?&]record=([A-Za-z0-9]+)/);
  if (queryMatch) return queryMatch[1];
  return '';
}

function normalizeBool(value) {
  return value === true || value === 'true' || value === 1 || value === '1';
}

function normalizeStringArray(value) {
  if (value === undefined || value === null || value === '') return [];
  if (Array.isArray(value)) {
    return value
      .map(v => String(v).trim())
      .filter(Boolean);
  }
  return String(value)
    .split(',')
    .map(v => v.trim())
    .filter(Boolean);
}

const title = firstNonEmpty(issue.title, body.title);
const description = firstNonEmpty(issue.description, body.description);
const priority = firstNonEmpty(issue.priority, body.priority, 'Medium');
const taskType = firstNonEmpty(issue.task_type, issue.taskType, body.task_type, body.taskType);
const repository = firstNonEmpty(issue.repository, body.repository);
const teamId = firstNonEmpty(issue.team_id, issue.teamId, body.team_id, body.teamId);
const stateId = firstNonEmpty(issue.state_id, issue.stateId, body.state_id, body.stateId, 'ab47e930-2517-4b23-93fa-302833013d2c');
const agentEnabled = normalizeBool(firstNonEmpty(issue.agent_enabled, issue.agentEnabled, body.agent_enabled, body.agentEnabled, true));
const modelLabel = firstNonEmpty(issue.model_label, issue.modelLabel, body.model_label, body.modelLabel);
const parentTaskUrl = firstNonEmpty(body.parent_task_url, body.parentTaskUrl, feishuInput.parent_task_url, feishuInput.parentTaskUrl);

// 每个 issue 调用一次时，blocked_by_issue_ids 必须传已经创建好的前置 Linear issue id / identifier。
// 语义：当前新 issue 被这些前置 issue 阻塞，也就是：前置 issue blocks 当前新 issue。
const blockedByIssueIds = normalizeStringArray(
  issue.blocked_by_issue_ids ??
  issue.blockedByIssueIds ??
  issue.blocked_by_linear_issue_ids ??
  issue.blockedByLinearIssueIds ??
  body.blocked_by_issue_ids ??
  body.blockedByIssueIds ??
  body.blocked_by_linear_issue_ids ??
  body.blockedByLinearIssueIds
);

const LINEAR_LABEL_IDS = {
  'use-codex': 'acd82840-6cb5-4c9e-bbc8-f52dbed01eac',
  'use-cursor': 'c654d731-c6eb-4113-ab96-192f3c5809b5'
};

const labelIds = [];
if (Array.isArray(issue.labelIds)) labelIds.push(...issue.labelIds);
if (LINEAR_LABEL_IDS[modelLabel]) labelIds.push(LINEAR_LABEL_IDS[modelLabel]);

const parentRecordId = firstNonEmpty(
  feishuInput.parent_record_id,
  feishuInput.parentRecordId,
  feishuInput.record_id,
  feishuInput.recordId,
  body.parent_record_id,
  body.parentRecordId,
  body.record_id,
  body.recordId,
  extractRecordIdFromUrl(parentTaskUrl)
);

const appToken = firstNonEmpty(feishuInput.app_token, feishuInput.appToken, body.app_token, body.appToken, DEFAULT_FEISHU_CONFIG.app_token);
const tableId = firstNonEmpty(feishuInput.table_id, feishuInput.tableId, body.table_id, body.tableId, DEFAULT_FEISHU_CONFIG.table_id);

if (!title) {
  throw new Error('缺少必要字段：issue.title 或 title');
}

if (!teamId) {
  throw new Error('缺少必要字段：issue.team_id / issue.teamId / team_id');
}

if (!appToken) {
  throw new Error('缺少必要字段：feishu.app_token / app_token。当前 workflow 不使用环境变量。');
}

if (!tableId) {
  throw new Error('缺少必要字段：feishu.table_id / table_id。当前 workflow 不使用环境变量。');
}

if (!parentRecordId) {
  throw new Error('缺少父任务 record_id：请传 parent_task_url，或 feishu.parent_record_id / record_id');
}

const linearInput = {
  teamId,
  title,
  description: [
    description,
    '',
    parentTaskUrl ? `飞书父任务：${parentTaskUrl}` : '',
    blockedByIssueIds.length ? `Blocked by：${blockedByIssueIds.join(', ')}` : '',
    `任务类型：${taskType}`,
    `优先级：${priority}`,
    `目标仓库：${repository}`,
    `是否启用 Agent：${agentEnabled}`
  ].filter(Boolean).join('\n'),
  stateId,
  ...(labelIds.length ? { labelIds: [...new Set(labelIds)] } : {})
};

for (const key of ['assigneeId', 'projectId', 'cycleId', 'parentId', 'estimate']) {
  const value = issue[key] ?? body[key];
  if (value !== undefined && value !== null && String(value).trim() !== '') {
    linearInput[key] = value;
  }
}

return [
  {
    json: {
      raw: body,
      title,
      description,
      priority,
      taskType,
      repository,
      teamId,
      stateId,
      agentEnabled,
      modelLabel,
      parent_task_url: parentTaskUrl,
      blocked_by_issue_ids: [...new Set(blockedByIssueIds)],
      linearInput,
      feishu: {
        app_token: appToken,
        table_id: tableId,
        record_id: parentRecordId,
        field_names: FIELD_NAMES
      }
    }
  }
];

