parameters.jsCode:
const original = $('标准化并校验 Agent 请求').first().json;
const response = $json;

if (response.errors?.length) {
  throw new Error('Linear GraphQL errors: ' + JSON.stringify(response.errors));
}

if (!response.data?.issueCreate?.success) {
  throw new Error('Linear issueCreate failed: ' + JSON.stringify(response));
}

const createdIssue = response.data.issueCreate.issue;
const blockers = Array.isArray(original.blocked_by_issue_ids) ? original.blocked_by_issue_ids : [];

function gqlString(value) {
  return JSON.stringify(String(value));
}

const relationMutations = blockers.map((blockerId, index) => {
  // Linear 语义：A blocks B。
  // 这里 issueId 是前置 blocker，relatedIssueId 是刚创建的当前 issue。
  return `r${index}: issueRelationCreate(input: { issueId: ${gqlString(blockerId)}, relatedIssueId: ${gqlString(createdIssue.id)}, type: blocks }) {
    success
    issueRelation {
      id
      type
      issue { id identifier title url }
      relatedIssue { id identifier title url }
    }
  }`;
});

const canCreateLinearRelations = relationMutations.length > 0;
const linearRelationRequest = canCreateLinearRelations ? {
  query: `mutation CreateIssueRelations {
${relationMutations.join('\n')}
}`
} : null;

return [{
  json: {
    ...original,
    linear_issue_id: createdIssue.id,
    linear_identifier: createdIssue.identifier,
    linear_title: createdIssue.title,
    linear_url: createdIssue.url,
    canCreateLinearRelations,
    linearRelationRequest
  }
}];

const base = $('准备 Linear 阻塞关系数据').first().json;
const response = $json;

if (response.errors?.length) {
  throw new Error('Linear issueRelationCreate GraphQL errors: ' + JSON.stringify(response.errors));
}

const relationKeys = Object.keys(response.data || {}).filter(key => key.startsWith('r'));
const failed = relationKeys.filter(key => response.data[key]?.success !== true);
if (failed.length) {
  throw new Error('Linear issueRelationCreate failed: ' + JSON.stringify(response));
}

const relations = relationKeys.map(key => response.data[key].issueRelation).filter(Boolean);

return [{
  json: {
    ...base,
    linear_relations_created: relations.length,
    linear_relations: relations
  }
}];

const original = $('准备 Linear 阻塞关系数据').first().json;
const relationChecked = $('检查 Linear 阻塞关系结果').isExecuted ? $('检查 Linear 阻塞关系结果').first().json : null;

const parentRecordId = original.feishu?.record_id || '';
const appToken = original.feishu?.app_token || '';
const tableId = original.feishu?.table_id || '';
const fieldNames = original.feishu?.field_names || {};

const canCreateFeishuSubtask = Boolean(
  appToken &&
  tableId &&
  parentRecordId &&
  fieldNames.parent_link
);

const blockers = Array.isArray(original.blocked_by_issue_ids) ? original.blocked_by_issue_ids : [];

function extractBaseBranch(description) {
  if (!description) return '';
  const lines = String(description).split(/\r?\n/);

  for (const line of lines) {
    const match = line.match(/(?:base\s*branch|base_branch|baseBranch|基准分支)\s*(?::|：|=|\bis\b)\s*(.+)$/i);
    if (!match) continue;

    const value = match[1]
      .trim()
      .replace(/^['"`]+|['"`]+$/g, '')
      .replace(/[，,;；。]+$/g, '')
      .trim();
    const branch = value.match(/^[^\s,，;；)）]+/);
    if (branch?.[0]) return branch[0].replace(/^['"`]+|['"`]+$/g, '');
  }

  return '';
}

const baseBranch = extractBaseBranch(original.description);
const baseBranchFieldName = fieldNames.base_branch || 'Base Branch';

const childFields = {
  [fieldNames.title]: original.title,
  [fieldNames.description]: [
    original.description || '',
    '',
    `Linear：${original.linear_url}`,
    original.parent_task_url ? `父任务：${original.parent_task_url}` : '',
    blockers.length ? `Blocked by：${blockers.join(', ')}` : '',
  ].filter(Boolean).join('\n'),
  [fieldNames.parent_link]: [parentRecordId],
  [fieldNames.linear_issue_id]: original.linear_identifier,
  // 你的 Linear URL 字段是文本字段（A= 图标），所以这里写字符串；
  // 如果将来改成 URL 字段，再改为 { text: original.linear_identifier, link: original.linear_url }。
  [fieldNames.linear_url]: original.linear_url,
  [fieldNames.agent_status]: original.agentEnabled ? '待触发' : '未启用',
  [fieldNames.task_type]: original.taskType || '',
  [fieldNames.priority]: original.priority || '',
  [fieldNames.repository]: original.repository || '',
  [baseBranchFieldName]: baseBranch
};

// 删除空字段名或空值，避免字段不存在/空值导致转换错误。
for (const key of Object.keys(childFields)) {
  const value = childFields[key];
  if (!key || key === 'undefined') {
    delete childFields[key];
    continue;
  }
  if (value === undefined || value === null || value === '') {
    delete childFields[key];
  }
}

return [{
  json: {
    ...original,
    canCreateFeishuSubtask,
    linear_relations_created: relationChecked?.linear_relations_created || 0,
    linear_relations: relationChecked?.linear_relations || [],
    feishu_child_record_fields: childFields
  }
}];

