(() => {
  const d = $('准备飞书子任务数据').first().json;
  const created = $('飞书 - 在原表创建子任务记录').isExecuted ? $('飞书 - 在原表创建子任务记录').first().json : null;
  const recordId = created?.data?.record?.record_id || created?.data?.record_id || created?.record?.record_id || null;
  return {
    code: 0,
    message: 'created',
    data: {
      ok: true,
      linear_issue_id: d.linear_issue_id,
      linear_identifier: d.linear_identifier,
      linear_title: d.linear_title,
      linear_url: d.linear_url,
      blocked_by_issue_ids: d.blocked_by_issue_ids || [],
      linear_relations_created: d.linear_relations_created || 0,
      feishu_subtask_created: Boolean(recordId),
      feishu_parent_record_id: d.feishu.record_id || null,
      feishu_child_record_id: recordId
    }
  };
})()
}}
